use verus::*;

verus! {

    /// Returns the maximum element of a non‐empty integer slice `a`.
    /// 
    /// Requires:
    ///   - `a.len() >= 1`
    /// Ensures:
    ///   - For all `j < a.len()`, `m >= a[j]`
    ///   - There exists some `j < a.len()` such that `m == a[j]`
    fn maxArray(a: &[int]) -> (m: int)
        requires
            a.len() >= 1,
        ensures
            // m is at least as large as every element
            forall |j: usize| j < a.len() ==> m >= a[j],
        ensures
            // m actually occurs in the array
            exists |j: usize| j < a.len() && a[j] == m,
    {
        // We will scan from index 1 to a.len(), maintaining:
        //   1) 1 <= i <= a.len()
        //   2) for all k < i, m >= a[k]
        //   3) there exists k < i with m == a[k]
        let mut i: usize = 1;
        let mut m: int = a[0];
        while i < a.len()
            invariant
                // bounds
                i <= a.len(),
            invariant
                // m is at least the max of the prefix [0..i)
                forall |k: usize| k < i ==> m >= a[k],
            invariant
                // m is witnessed in the prefix [0..i)
                exists |k: usize| k < i && a[k] == m,
            decreases
                a.len() - i,
        {
            if a[i] > m {
                m = a[i];
            }
            i += 1;
        }
        // At loop exit, i == a.len(), so the invariants imply the postconditions
        m
    }
}